INSERT INTO `lists_lang` (`id`, `main_id`, `lang`, `title`, `anons`, `body`, `anonsImage`, `bodyImage`, `views`, `enabled`, `creator_id`, `modifier_id`, `created_at`, `updated_at`, `pdf`) VALUES
(1, 1, 'ru', 'ЖУРНАЛИСТЫ ЗНАКОМЯТСЯ С СИСТЕМОЙ АСКУЭ', 'В целях ознакомления с работой по внедрению автоматизированной системы учета и контроля электрической энергии, группа местных и международных специалистов и журналистов находится в городе Самарканд.', '<p>В мероприятии, организованном АО &laquo;Региональные электрические сети&raquo; совместно с Азиатским банком развития, принимают участие представители стран-членов Центральноазиатского регионального экономического сотрудничества (ЦАРЭС).</p>\r\n\r\n<p>В целях исполнения постановления Президента Республики Узбекистан от 23 октября 2018 года &laquo;О мерах по ускоренному развитию и обеспечению финансовой устойчивости электроэнергетической отрасли&raquo; АО &laquo;Региональные электрические сети&raquo; по всей республике активно ведётся работа по поэтапному внедрению автоматизированной системы учета и контроля электрической энергии (АСКУЭ). В рамках пресс-тура участники мероприятия получили возможность изучить данный процесс на месте.</p>\r\n\r\n<p><img alt=\"\" src=\"/uploads/464bfc97-de8d-52fb-0787-c387bdfc2b97_media_.jpg\" /></p>\r\n\r\n<p>Нужно отметить, на сегодняшний день в 45 городах и районах страны установлены более 1,5 миллиона приборов учета электрической энергии. К концу текущего года установка современных приборов учета электрической энергии будет завершена для 2,5 миллиона потребителя, а до конца 2020 года будут подключены к автоматизированной системе контроля и учета электроэнергии (АСКУЭ) 7 млн. потребителя.</p>\r\n\r\n<p>В частности, совместно с южнокорейской компанией &laquo;KT Corporation&raquo; проводятся работы по установке современных приборов учета электрической энергии в Бухарской, Джизакской и Самаркандской областях.</p>\r\n\r\n<p><img alt=\"\" src=\"/uploads/3e55c09c-b799-5f01-3436-de773091d039_media_.jpg\" /></p>\r\n\r\n<p>&ndash; В области на сегодняшний день насчитывается 817&nbsp;862 потребителя электроэнергии, &ndash; говорит начальник отдела АСКУЭ Самаркандского территориального предприятия электрических сетей Валижон Киличев. &ndash; 778 247 из них &ndash; это бытовые и 39 615 &ndash; юридические потребители.</p>\r\n\r\n<p><img alt=\"\" src=\"/uploads/1af0a14f-a4b3-b841-cf61-65cce24ac693_media_.jpg\" /></p>\r\n\r\n<p>По состоянию на 10 сентября 2019 года, около 267 тыс. потребителям были установлены современные приборы учета электрической энергии, соответствующие АСКУЭ.&nbsp;Из них 52 300 потребителя уже подключены к системе и теперь работы по контролю учета потребления электроэнергии и расчета оплаты ведутся автоматизировано. К установке электросчетчиков по всему региону были привлечены 234 специалиста, что делает процесс более быстрым и эффективным.</p>\r\n\r\n<p><img alt=\"\" src=\"/uploads/48ba4685-11bc-c7f4-ead9-882f3fc4f086_media_.jpg\" /></p>\r\n\r\n<p>На мероприятии журналистам сегодня были продемонстрированы презентации о преимуществах данной системы. Основная цель мероприятия &ndash; донести до широкой аудитории проделанную работу совместно с международными партнерами. Что касается &laquo;умных&raquo; счетчиков электроэнергии, у нас тоже есть похожая система, но она немного отличается от вашей. Несмотря на то, что мы многое узнали от узбекских и южнокорейских экспертов об этой системе, мы не перестаем задавать вопросы. Такой формат мероприятия делает его более продуктивным.&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Пресс-служба АО &laquo;Региональные электрические сети&raquo;</p>\r\n', 'abf43c79-c789-b9d2-438e-6083e7827c4d_news_1.jpg', 'a3bc81f9-7b6f-e8bc-2c54-c8b999b48c18_news_1.jpg', 2649, 1, 3, NULL, 1569574885, 1760938530, ''),
(2, 2, 'ru', 'ПРОВЕДЕНИЕ 18-19 СЕНТЯБРЯ ТЕКУЩЕГО ГОДА ЭНЕРГЕТИЧЕСКОГО ПРЕСС-ТУРА ДЛЯ МЕЖДУНАРОДНЫХ ЖУРНАЛИСТОВ ЦАРЭС В г. САМАРКАНД', 'В рамках Международной конференции и инвестиционного форума по энергетике, реализуемой с 16 по 22 сентября 2019 г. Министерством энергетики Республики Узбекистан при официальной поддержке АБР, с 18 по 19 сентября 2019 г. намечено проведение энергетического пресс-тура, организованный для стран Центральноазиатского регионального экономического сотрудничества.', '<p style=\"margin:0cm 0cm 8pt\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Calibri,sans-serif\">Основной целью пресс-тура, является ознакомление международных журналистов с ходом работ АО &laquo;Региональные электрические сети&raquo; по подключению потребителей электрической энергии к автоматизированной системе контроля и учета электроэнергии (АСКУЭ), реализуемой в соответствии с постановлением Президента Республики Узбекистан от 23 октября 2018 года № ПП-3981 &laquo;О мерах по ускоренному развитию и обеспечению финансовой устойчивости электроэнергетической отрасли&raquo;.&nbsp;&nbsp;</span></span></span></p>\r\n\r\n<p style=\"margin:0cm 0cm 8pt\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Calibri,sans-serif\">&nbsp; На мероприятии специалисты расскажут о преимуществах работы &laquo;умных&raquo; счетчиков, правилах их использования и о других интересных фактах устанавливаемых приборов учета электрической энергии. В то же время будут даны подробные ответы на вопросы участников пресс-тура.</span></span></span></p>\r\n\r\n<p style=\"margin:0cm 0cm 8pt\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Calibri,sans-serif\">Приглашаем всех представителей СМИ и заинтересованных лиц для принятия участия в данном мероприятии.</span></span></span></p>\r\n\r\n<p style=\"margin:0cm 0cm 8pt\">&nbsp;</p>\r\n\r\n<p><strong><span style=\"font-size:11.0pt\"><span style=\"line-height:107%\"><span style=\"font-family:&quot;Calibri&quot;,&quot;sans-serif&quot;\">Пресс-служба АО &laquo;Региональные электрические сети&raquo;</span></span></span></strong></p>\r\n', '67786e9c-58ed-1579-c3f4-5831560a5b3b_lists_2.png', 'bcfe8591-da13-8de5-0297-ae235787145f_lists_2.png', 2243, 1, 3, NULL, 1569575573, 1760945776, ''),
(3, 3, 'ru', 'АО «РЕГИОНАЛЬНЫЕ ЭЛЕКТРИЧЕСКИЕ СЕТИ» УЧАСТВУЕТ В XVI МЕЖДУНАРОДНОМ КОНКУРСЕ ПОВЫШЕНИЯ КВАЛИФИКАЦИИ', 'С 14 по 25 сентября 2019 года в г.Кызылорда (Республика Казахстан) намечено проведение XVI Международного соревнования профессионального мастерства среди персонала электроэнергетической отрасли государств СНГ, где будет также участвовать команда из Республики Узбекистан АО «Региональные электрические сети».', '<p style=\"margin:0cm 0cm 8pt\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Calibri,sans-serif\">Основными целями и задачами соревнований являются: </span></span></span></p>\r\n\r\n<p style=\"margin:0cm 0cm 8pt\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Calibri,sans-serif\">&bull; повышение и оценка уровня профессиональной подготовки персонала по обслуживанию ВЛ 110 кВ и выше национальных энергосистем государств - участников СНГ, </span></span></span></p>\r\n\r\n<p style=\"margin:0cm 0cm 8pt\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Calibri,sans-serif\">&bull; повышение культуры безопасности труда,</span></span></span></p>\r\n\r\n<p style=\"margin:0cm 0cm 8pt\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Calibri,sans-serif\">&bull; повышение квалификации персонала, качества работ и безопасности при обслуживании ВЛ 110 кВ и выше, снижение травматизма, </span></span></span></p>\r\n\r\n<p style=\"margin:0cm 0cm 8pt\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Calibri,sans-serif\">&bull; обмен передовым опытом при эксплуатации оборудования и выполнении ремонтных работ на высоковольтных линиях электропередач,</span></span></span></p>\r\n\r\n<p style=\"margin:0cm 0cm 8pt\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Calibri,sans-serif\">&bull; укрепление традиционных профессиональных связей энергетиков государств - участников соревнований. </span></span></span></p>\r\n\r\n<p style=\"margin:0cm 0cm 8pt\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Calibri,sans-serif\">Пожелаем удачи и поддержим команду АО &laquo;Региональные электрические сети&raquo;!</span></span></span></p>\r\n\r\n<p style=\"margin:0cm 0cm 8pt\">&nbsp;</p>\r\n\r\n<p style=\"margin:0cm 0cm 8pt\"><strong><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Calibri,sans-serif\">Пресс-служба АО &ldquo;Региональные электрические сети&rdquo; </span></span></span></strong></p>\r\n', 'c983ca97-cfbc-4b3b-a3fa-59d132b52d91_lists_3.jpg', '9adc0257-61d2-817a-44ab-7588c9fd4b28_lists_3.jpg', 2322, 1, 3, NULL, 1569575796, 1760895166, ''),
