(40, 25, 'ru', 'Устав и внутренние положения ', NULL, '<div style=\"background:#eeeeee;border:1px solid #cccccc;padding:5px 10px;\"><a href=\"http://het.uz/uploads/adddf67d-d9ee-97c6-ac21-ebf074aeb0c6_media_.pdf\"><strong><big>УСТАВ АО &quot;РЕГИОНАЛЬНЫЕ ЭЛЕКТРИЧЕСКИЕ СЕТИ&quot;&nbsp;</big></strong></a></div>\r\n\r\n<div style=\"background:#eeeeee;border:1px solid #cccccc;padding:5px 10px;\">&nbsp;&nbsp;<strong>информация представлена&nbsp;на узбекском языке (новый)</strong></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div style=\"background:#eeeeee;border:1px solid #cccccc;padding:5px 10px;\"><a href=\"http://het.uz/uploads/779418c1-6bb5-7059-83e7-1770bf850054_media_.pdf\"><strong><big>УСТАВ АО &quot;РЕГИОНАЛЬНЫЕ ЭЛЕКТРИЧЕСКИЕ СЕТИ&quot;&nbsp;</big></strong></a>&nbsp; &nbsp;</div>\r\n\r\n<div style=\"background:#eeeeee;border:1px solid #cccccc;padding:5px 10px;\">&nbsp;&nbsp;<strong>информация представлена&nbsp;на узбекском языке</strong></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div style=\"background:#eeeeee;border:1px solid #cccccc;padding:5px 10px;\"><strong><a href=\"http://het.uz/uploads/59efcb87-f49d-5cea-3ede-5a9b916b8384_media_.pdf\"><big>УСТАВ АО &quot;РЕГИОНАЛЬНЫЕ ЭЛЕКТРИЧЕСКИЕ СЕТИ&quot;&nbsp;</big></a><br />\r\nинформация представлена&nbsp;на узбекском языке</strong></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div style=\"background:#eeeeee;border:1px solid #cccccc;padding:5px 10px;\"><strong><a href=\"http://het.uz/uploads/25567df7-9e54-26b2-5ee4-c0cb346ff99d_media_.pdf\">ПОЛОЖЕНИЕ О ВНУТРЕННЕМ КОНТРОЛЕ АКЦИОНЕРНОГО ОБЩЕСТВА &laquo;HUDUDIY ELEKTR TARMOQLARI&raquo;</a></strong></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div style=\"background:#eeeeee;border:1px solid #cccccc;padding:5px 10px;\"><strong><a href=\"http://het.uz/uploads/8521cf57-2dc9-0124-606f-da1cd37a543d_media_.pdf\">ПОЛОЖЕНИЕ О ДИВИДЕНДНОЙ ПОЛИТИКЕ АКЦИОНЕРНОГО ОБЩЕСТВА &laquo;HUDUDIY ELEKTR TARMOQLARI&raquo;</a></strong></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div style=\"background:#eeeeee;border:1px 