(44, 27, 'ru', 'Решения Общего собрания акционеров', NULL, '<div style=\"background:#eeeeee;border:1px solid #cccccc;padding:5px 10px;\"><a href=\"/uploads/9c663f32-f6e7-4b95-0940-4ef2beae3554_media_.pdf\">Решение ед.акционера №1</a></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div style=\"background:#eeeeee;border:1px solid #cccccc;padding:5px 10px;\"><a href=\"/uploads/11899340-aa96-a97b-7a38-9f6aa4634c50_media_.pdf\">Решение ед.акционера №2</a></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div style=\"background:#eeeeee;border:1px solid #cccccc;padding:5px 10px;\"><a href=\"/uploads/23de0ae5-2703-3d0c-8ddb-401cb1990f7c_media_.pdf\">Решение ед.акционера №3</a></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div style=\"background:#eeeeee;border:1px solid #cccccc;padding:5px 10px;\"><a href=\"/uploads/0c715ff9-e8a5-0088-8b24-10d3dec1cb20_media_.pdf\">Решение ед.акционера №4</a></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div style=\"background:#eeeeee;border:1px solid #cccccc;padding:5px 10px;\"><a href=\"/uploads/845fba2b-96e0-96df-f5ac-6e397f4053ff_media_.pdf\">Решение ед.акционера №5</a></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n', NULL, NULL, 687, 1, 3, NULL, 1569839138, 1760953864, ''),
(45, 28, 'oz', 'Dividendlar to\'lovi', NULL, '<p align=\"center\" style=\"text-align:center; margin:0cm 0cm 0.0001pt\">&nbsp;</p>\r\n\r\n<p align=\"center\" style=\"text-align:center; margin:0cm 0cm 0.0001pt\"><big><strong><span style=\"font-size:10pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span lang=\"UZ-CYR\" style=\"font-size:12.0pt\">DIQQAT! DIQQAT! DIQAT!</span></span></span></strong></big></p>\r\n\r\n<p align=\"center\" style=\"text-align:center; margin:0cm 0cm 0.0001pt\">&nbsp;</p>\r\n\r\n<p align=\"center\" style=\"text-align:center; margin:0cm 0cm 0.0001pt\"><big><span style=\"font-size:10pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span lang=\"UZ-CYR\" style=\"font-size:12.0pt\">&ldquo;Hududiy elektr tarmoqlari&rdquo; AJ ushbu bilan Jamiyatning barcha ovoz beruvchi aksiyalari Yagona aksiyadorining 2024 yil 20 avgustdagi 5-sonli qaroriga binoan 2023 yil yakunlari bо&lsquo;yicha Jamiyatning <strong>xar bir dona imtiyozli aksiyasi nominal qiymatiga nisbatan 25 foiz miqdorida dividendlar tо&lsquo;lash </strong>yuzasidan qaror qabul qilingan!</span></span></span></big></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 0.0001pt\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 0.0001pt\"><big><span style=\"font-size:10pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span lang=\"UZ-CYR\" style=\"font-size:12.0pt\">Shunga kо&lsquo;ra <strong>hurmatli aksiyadolar</strong>, Sizdan о&lsquo;zingizga tegishli bо&lsquo;lgan &ldquo;Hududiy elektr tarmoqlari&rdquo; AJning imtiyozli aksiyalari bо&lsquo;yicha dividendlarni quyida qayd etilgan shakldagi arizani Jamiyatning rasmiy elektron info@het.uz pochta manziliga yoki bevosita yozma ravishda Toshkent shahri, Osiyo kо&lsquo;chasi 8-uy manzili bо&lsquo;yicha (pochta indeksi 100084) yuborgan holda talab qilib olishingiz mumkinligini ma&rsquo;lum qilamiz!</span></span></span></big></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 0.0001pt\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 0.0001pt\"><big><strong><span lang=\"UZ-CYR\" style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Ariza shakli (namunasi):</span></span></strong></big></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 0.0001pt\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 0.0001pt\">&nbsp;</p>\r\n\r\n<table class=\"Table\" style=\"width:473.5pt; border-collapse:collapse; border:undefined\" width=\"631\">\r\n	<tbody>\r\n		<tr>\r\n			<td style=\"width:218.05pt; padding:0cm 5.4pt 0cm 5.4pt\" valign=\"top\" width=\"291\">\r\n			<p style=\"margin:0cm 0cm 0.0001pt\">&nbsp;</p>\r\n			</td>\r\n			<td style=\"width:255.45pt; padding:0cm 5.4pt 0cm 5.4pt\" valign=\"top\" width=\"341\">\r\n			<p align=\"center\" style=\"text-align:center; margin:0cm 0cm 0.0001pt\"><big><strong><span style=\"font-size:10pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span lang=\"UZ-CYR\" style=\"font-size:12.0pt\">&laquo;Hududiy elektr tarmoqlari&raquo; AJ</span></span></span></strong></big></p>\r\n\r\n			<p align=\"center\" style=\"text-align:center; margin:0cm 0cm 0.0001pt\"><big><strong><span style=\"font-size:10pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span lang=\"UZ-CYR\" style=\"font-size:12.0pt\">Boshqaruv raisiga</span></span></span></strong></big></p>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p align=\"center\" style=\"text-align:center; margin:0cm 0cm 0.0001pt\"><big><strong><span lang=\"UZ-CYR\" style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Ariza</span></span></strong></big></p>\r\n\r\n<p align=\"center\" style=\"text-align:center; margin:0cm 0cm 0.0001pt\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 0.0001pt\"><big><span style=\"font-size:10pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span lang=\"UZ-CYR\" style=\"font-size:12.0pt\">Sizdan, menga tegishli bо&lsquo;lgan &laquo;Hududiy elektr tarmoqlari&raquo; AJning imtiyozli aksiyalari bо&lsquo;yicha 2023 yil yakunlari yuzasidan hisoblangan dividendlarni belgilangan tartibda quyidagi rekvizitlarga о&lsquo;tkazib berishingizni sо&lsquo;rayman:</span></span></span></big></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 0.0001pt\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 0.0001pt\"><big><span lang=\"UZ-CYR\" style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Aksiyadorning plastik karta raqami</span></span><span style=\"font-size:10pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span lang=\"UZ-CYR\" style=\"font-size:14.0pt\"><span style=\"line-height:115%\">: _______________________ / </span></span></span></span></span><span lang=\"UZ-CYR\" style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">(F.I.SH)</span></span></big></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 0.0001pt\"><big><span lang=\"UZ-CYR\" style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Bank tranzit xisob raqami</span></span><span style=\"font-size:10pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span lang=\"UZ-CYR\" style=\"font-size:14.0pt\"><span style=\"line-height:115%\">: ________________________</span></span></span></span></span></big></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 0.0001pt\"><big><span lang=\"UZ-CYR\" style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Bank nomi</span></span><span style=\"font-size:10pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span lang=\"UZ-CYR\" style=\"font-size:14.0pt\"><span style=\"line-height:115%\">: &ldquo;_____________________________&rdquo; _______________