(57, 34, 'oz', 'Tarmoqlarning texnik holati', '', '<p style=\"text-align: center;\"><strong><big>Elektr tarmog&lsquo;i xo&lsquo;jaligi ob&#39;ektlarini muhofaza qilish qoidalari</big></strong></p>\r\n\r\n<p><big>&nbsp; &nbsp; &nbsp; O&lsquo;zbekiston Respublikasi Vazirlar Mahkamasining 2018 yil 26 dekabrdagi &ldquo;Elektr tarmog&lsquo;i xo&lsquo;jaligi ob&#39;ektlarini muhofaza qilish qoidalarini tasdiqlash to&lsquo;g&lsquo;risida&rdquo;gi qarori bilan elektr tarmog&lsquo;i xo&lsquo;jaligi ob&#39;ektlarini muhofaza zonalari belgilab berilgan...</big></p>\r\n\r\n<ul>\r\n	<li><big>&bull; 1 kV gacha kuchlanishli tarmoqlar uchun &ndash; 2 metr (binolarni devorlari, konstruksiyalar va hokazolar bo&lsquo;ylab o&lsquo;tkazilgan o&lsquo;zini o&lsquo;zi tutib turuvchi yoki izolyasiyalangan simli tarmoqlar uchun muhofaza zonasi normativ-huquqiy hujjatlarga muvofiq o&lsquo;rnatilgan. Bunday tarmoqlardan ruxsat etilgan eng kam masofalar bilan aniqlanadi);</big></li>\r\n	<li><big>&bull; 20 kVgacha kuchlanishli tarmoqlar uchun &ndash; 10 metr (aholi punktlari chegaralarida joylashgan o&lsquo;zini o&lsquo;zi tutib turuvchi yoki izolyasiyalangan simli tarmoqlari uchun 5 metr);</big></li>\r\n	<li><big>&bull; &nbsp;35 kV kuchlanishli tarmoqlar uchun &ndash; 15 metr;</big></li>\r\n	<li><big>&bull; 110 kV kuchlanishli tarmoqlar uchun &ndash; 20 metr;</big></li>\r\n</ul>\r\n', '614988e2-0d7b-83f3-84f3-b1c40b1ee387_lists_57.jpg', '08731290-9c66-775c-a032-9046b5bfea5b_lists_57.jpg', 34808, 1, 3, NULL, 1569997463, 1760972431, ''),
(58, 34, 'ru', 'Техническое состояние сетей', '', '<p style=\"text-align: center;\"><strong><big>Правила охраны объектов электросетевого хозяйства</big></strong></p>\r\n\r\n<p><big>Охранные зоны объектов электросетевого хозяйства устанавливаются в соответствии с &nbsp;Постановлением Кабинета Министров Республики Узбекистан &laquo;Об утверждении правил охраны объектов электросетевого хозяйства&raquo; от 26 декабря 2018 г. В частности:</big></p>\r\n\r\n<ul>\r\n	<li><big>&bull; &nbsp;до 1 киловольта &ndash; 2 метра (для линий с самонесущими или изолированными проводами, проложенных по стенам зданий, конструкциям и т.д., охранная зона определяется в соответствии с установленными нормативно-правовыми актами минимальными допустимыми расстояниями от таких линий);</big></li>\r\n	<li><big>&bull; &nbsp;20 киловольт &ndash; 10 метров (5 метров для линий с самонесущими или изолированными проводами, размещенных в границах населенных пунктов);</big></li>\r\n	<li><big>&bull; &nbsp;35 киловольт &ndash; 15 метров;</big></li>\r\n	<li><big>&bull; &nbsp;110 киловольт &ndash; 20 метров.</big></li>\r\n</ul>\r\n', 'c3561a62-82ad-5a86-2245-afee98725326_lists_58.jpg', '5c01447c-8b97-a2ba-a178-d330099c8a7b_lists_58.jpg', 8500, 1, 3, NULL, 1569997475, 1760958665, ''),
(59, 35, 'oz', 'Interaktiv davlat xizmatlari', 'Batafsil', '<div style=\"background: rgb(238, 238, 238); border: 1px solid rgb(204, 204, 204); padding: 5px 10px; text-align: center;\"><big><a href=\"http://het.uz/uploads/9f7ee70f-19df-e859-d58d-4d0fc852d9a5_media_.pdf\"><strong>O&lsquo;zbekiston Respublikasi Vazirlar Mahkamasining Qarori&nbsp;<br />\r\nYuridik va jismoniy shaxslarni elektr tarmoqlariga ulash bо&lsquo;yicha davlat xizmatlari kо&lsquo;rsatishning ma&rsquo;muriy reglamentini tasdiqlash tо&lsquo;g&lsquo;risida</strong></a></big></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div>\r\n<div style=\"background: rgb(238, 238, 238); border: 1px solid rgb(204, 204, 204); padding: 5px 10px; text-align: center;\"><big><strong><a href=\"https://my.gov.uz/oz/service/sub-services?domen=13&amp;id=1\">Interaktiv davlat xizmatlari ro`yxati</a></strong></big></div>\r\n\r\n<p style=\"text-align: center;\"><big><strong>&nbsp;</strong></big></p>\r\n</div>\r\n\r\n<div style=\"background: rgb(238, 238, 238); border: 1px solid rgb(204, 204, 204); padding: 5px 10px; text-align: center;\"><big><strong><a href=\"https://my.soliq.uz/searchtin/index?lang=uz\">STIRingizni aniqlang</a></strong></big></div>\r\n\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n\r\n<p style=\"text-align: center;\"><big><strong>ELEKTR TARMOQLARIGA ULANISH UCHUN TEXNIK SHARTLARNI OLISH </strong></big></p>\r\n\r\n<p style=\"text-align: center;\"><big><strong>TARTIBI</strong></big></p>\r\n\r\n<table class=\"table table-bordered table-striped\">\r\n	<tbody>\r\n		<tr>\r\n			<td nowrap=\"nowrap\">\r\n			<p style=\"text-align: center;\"><strong>№</strong></p>\r\n			</td>\r\n			<td nowrap=\"nowrap\">\r\n			<p style=\"text-align: center;\"><strong>Хизмat nomi</strong></p>\r\n			</td>\r\n			<td nowrap=\"nowrap\">\r\n			<p style=\"text-align: center;\"><strong>Muddati</strong></p>\r\n			</td>\r\n		</tr>\r\n		<tr style=\"height:15.0pt\">\r\n			<td nowrap=\"nowrap\">\r\n			<p style=\"text-align: center;\"><strong>1</strong></p>\r\n			</td>\r\n			<td nowrap=\"nowrap\">\r\n			<p>20 kVt dan yuqori bо&lsquo;lmagan elektr tarmoqlariga ulanish uchun texnik</p>\r\n\r\n			<p>shartlarni olish</p>\r\n			</td>\r\n			<td nowrap=\"nowrap\">\r\n			<p>3 ish kuni</p>\r\n			</td>\r\n		</tr>\r\n		<tr style=\"height:15.0pt\">\r\n			<td nowrap=\"nowrap\">\r\n			<p style=\"text-align: center;\"><strong>2</strong></p>\r\n			</td>\r\n			<td nowrap=\"nowrap\">\r\n			<p>20 kVt dan 50 kVt gacha elektr tarmoqlariga ulanish uchun texnik</p>\r\n\r\n			<p>shartlarni olish</p>\r\n			</td>\r\n			<td nowrap=\"nowrap\">\r\n			<p>3 ish kuni</p>\r\n			</td>\r\n		</tr>\r\n		<tr style=\"height:15.0pt\">\r\n			<td nowrap=\"nowrap\">\r\n			<p style=\"text-align: center;\"><strong>3</strong></p>\r\n			</td>\r\n			<td nowrap=\"nowrap\">\r\n			<p>50 kVt dan yuqori elektr tarmoqlariga ulanish uchun texnik</p>\r\n\r\n			<p>shartlarni olish</p>\r\n			</td>\r\n			<td nowrap=\"nowrap\">\r\n			<p>3 ish kuni</p>\r\n			</td>\r\n		</tr>\r\n		<tr style=\"height:15.0pt\">\r\n			<td nowrap=\"nowrap\">\r\n			<p style=\"text-align: center;\"><strong>4</strong></p>\r\n			</td>\r\n			<td nowrap=\"nowrap\">\r\n			<p>Quvvati 20 kVtgacha bо&lsquo;lgan maishiy iste&rsquo;molchilarni elektr</p>\r\n\r\n			<p>tarmoqlariga ulash</p>\r\n			</td>\r\n			<td nowrap=\"nowrap\">\r\n			<p>10 ish kuni</p>\r\n			</td>\r\n		</tr>\r\n		<tr style=\"height:15.0pt\">\r\n			<td nowrap=\"nowrap\">\r\n			<p style=\"text-align: center;\"><strong>5</strong></p>\r\n			</td>\r\n			<td nowrap=\"nowrap\">\r\n			<p>Elektr energiyasini hisobga olish tizimini plombalash va elektr</p>\r\n\r\n			<p>ta&rsquo;minoti shartnomasini tuzish</p>\r\n			</td>\r\n			<td nowrap=\"nowrap\">\r\n			<p>1 ish kuni</p>\r\n			</td>\r\n		</tr>\r\n		<tr style=\"height:15.0pt\">\r\n			<td nowrap=\"nowrap\">\r\n			<p style=\"text-align: center;\"><strong>6</strong></p>\r\n			</td>\r\n			<td nowrap=\"nowrap\">\r\n			<p>Quvvati 20 kVtdan yuqori bо&lsquo;lgan elektr energiyasi iste&rsquo;molchilari</p>\r\n\r\n			<p>uchun elektr ta&rsquo;minoti loyihasini kelishish</p>\r\n			</td>\r\n			<td nowrap=\"nowrap\">\r\n			<p>2 ish kuni</p>\r\n			</td>\r\n		</tr>\r\n		<tr style=\"height:15.0pt\">\r\n			<td nowrap=\"nowrap\">\r\n			<p style=\"text-align: center;\"><strong>7</strong></p>\r\n			</td>\r\n			<td nowrap=\"nowrap\">\r\n			<p>Quvvati 20 kVtdan yuqori bо&lsquo;lgan elektr energiyasi iste&rsquo;molchilarining</p>\r\n\r\n			<p>elektr qurilmalarini ishga tushirish uchun bayonnoma olish</p>\r\n			</td>\r\n			<td nowrap=\"nowrap\">\r\n			<p>3-5 ish kuni</p>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<div><big><strong>Eslatma:</strong><em> Davlat xaridlari markazi orqali xizmatdan foydalanish narxi bazaviy hisoblash miqdori (BHM)ning 10 foizini tashkil etadi, onlayn platforma orqali &ndash; bepul.</em></big></div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div style=\"background: rgb(238, 238, 238); border: 1px solid rgb(204, 204, 204); padding: 5px 10px; text-align: center;\"><big><strong><a href=\"https://hetk.uz/uz/service/all-services\">Onlayn platforma orqali xizmatlar</a></strong></big></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n', 'f978afee-8c3e-2f2a-11e5-b66e900a7a6e_lists_59.jpg', 'b6a39ec7-ba4e-7cb4-6965-81474e6a138a_lists_59.jpg', 85799, 1, 3, NULL, 1569997589, 1760970009, ''),
(60, 35, 'ru', 'Интерактивные государственные услуги ', 'Подробнее', '<div>\r\n<div>\r\n<div style=\"background: rgb(238, 238, 238); border: 1px solid rgb(204, 204, 204); padding: 5px 10px; text-align: center;\"><strong><big><a href=\"http://het.uz/uploads/e5d7c82b-9ae8-b1a7-6110-1a309f9ddeaa_media_.pdf\">Постановление Кабинета Министров Республики Узбекистан<br />\r\nОб утверждении административных регламентов оказания государственных услуг по подключению к инженерно-коммуникационным сетям</a></big></strong></div>\r\n</div>\r\n\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n</div>\r\n\r\n<div style=\"background: rgb(238, 238, 238); border: 1px solid rgb(204, 204, 204); padding: 5px 10px; text-align: center;\"><strong><big><a href=\"https://my.gov.uz/ru/service/sub-services?domen=13&amp;id=1\">Перечень интерактивных государственных услуг</a></big></strong></div>\r\n\r\n<p style=\"text-align: center;\">&nbsp;&nbsp;</p>\r\n\r\n<div style=\"background: rgb(238, 238, 238); border: 1px solid rgb(204, 204, 204); padding: 5px 10px; text-align: center;\"><strong><big><a href=\"https://my.soliq.uz/searchtin/index?lang=ru\">Узнайте свой ИНН</a></big></strong></div>\r\n', '2809b626-b36e-b502-d622-1fce32393a78_lists_60.jpg', '970faf69-4cfc-581f-486f-14126396b2e9_lists_60.jpg', 23109, 1, 3, NULL, 1569997597, 1760964576, ''),
