(99, 55, 'oz', 'Kuzatuv kengashi tarkibi', NULL, '<table class=\"table table-bordered table-striped\">\r\n	<tbody>\r\n		<tr>\r\n			<td>\r\n			<p>&nbsp;</p>\r\n			</td>\r\n			<td>\r\n			<p>F.I.Sh</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Ish joyi</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Lavozimi</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">&ldquo;Hududiy elektr tarmoqlari&rdquo; AJ boshqaruv organidagi lavozimi</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>1</p>\r\n			</td>\r\n			<td>\r\n			<p>Kudbiyev Sherzod Davlyatovich</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Davlat soliq qo&lsquo;mitasi</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Raisi</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Kuzatuv kengashi raisi</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>2</p>\r\n			</td>\r\n			<td>\r\n			<p>Raximova Gulnora Xashimovna</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Iqtisodiyot va moliya vazirligi</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Vazir o&lsquo;rinbosari</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Kuzatuv kengashi a&rsquo;zosi</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>3</p>\r\n			</td>\r\n			<td>\r\n			<p>Miraliyev Alisher Erkinovich</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Davlat aktivlarini boshqarish agentligi</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Direktor o&lsquo;rinbosari</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Kuzatuv kengashi a&rsquo;zosi</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>4</p>\r\n			</td>\r\n			<td>\r\n			<p>Raupov Anvar Abdirashidovich</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">&ldquo;Olmaliq KMK&rdquo; AJ tarkibidagi &ldquo;O&lsquo;zbekiston texnologik metallar kombinati&rdquo; AJ</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Boshqaruvi raisi kotibiyati boshlig&lsquo;i</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Kuzatuv kengashi a&rsquo;zosi</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>5</p>\r\n			</td>\r\n			<td>\r\n			<p>Avazov Alisher Farxod o&lsquo;g&lsquo;li</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">&ldquo;UzAssates&rdquo; AJ</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Bo&lsquo;lim boshlig&lsquo;i</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Kuzatuv kengashi a&rsquo;zosi</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>6</p>\r\n			</td>\r\n			<td>\r\n			<p>Fatma Utan</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">-</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">-</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Kuzatuv kengashi mustaqil a&rsquo;zosi</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p>7</p>\r\n			</td>\r\n			<td>\r\n			<p>Igor Zaporoshenko</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">-</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">-</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Kuzatuv kengashi mustaqil a&rsquo;zosi</p>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n', NULL, NULL, 23091, 1, 3, NULL, 1570103552, 1760975102, '');
