(101, 56, 'oz', 'Ijro organi', NULL, '<p style=\"text-align: center;\"><big><strong>&ldquo;HUDUDIY ELEKTR TARMOQLARI&rdquo; AJ IJROIYA ORGANI TARKIBI&nbsp;</strong></big></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<table class=\"table table-bordered table-striped\">\r\n	<tbody>\r\n		<tr>\r\n			<td>\r\n			<p style=\"text-align: center;\">№</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">F.I.SH</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">&ldquo;Hududiy elektr tarmoqlari&rdquo; AJ</p>\r\n\r\n			<p style=\"text-align: center;\">Ijroya organidagi lavozimi</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p style=\"text-align: center;\">1</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Askarov Asrorjon Akramovich</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Boshqaruv raisi</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p style=\"text-align: center;\">2</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Vakant</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Boshqaruv raisining elektr tarmoqlaridan foydalanish bо&lsquo;yicha birinchi о&lsquo;rinbosari</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p style=\"text-align: center;\">3</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Gaybullayev Alvar Keldiyorovich</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Boshqaruv raisining transformatsiya, investitsiya, innovatsion rivojlanish, raqamlashtirish va axborot texnologiyalari masalalari bо&lsquo;yicha birinchi о&lsquo;rinbosari</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p style=\"text-align: center;\">4</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Vakant&nbsp;</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Boshqaruv raisining iqtisod va moliya masalalari bо&lsquo;yicha о&lsquo;rinbosari</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p style=\"text-align: center;\">5</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Nosirov Dilshod Baxodirovich</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Boshqaruv raisining kapital qurilish bо&lsquo;yicha о&lsquo;rinbosari</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p style=\"text-align: center;\">6</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Alimardonov Oybek Jumakulovich</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Boshqaruv raisining rejim va kadrlar bо&lsquo;yicha о&lsquo;rinbosari</p>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n', NULL, NULL, 17597, 1, 3, NULL, 1570104388, 1760975107, ''),
(102, 56, 'ru', 'Исполнительный орган', NULL, '<p style=\"text-align: center;\"><big>Состав Исполнительного органа<br />\r\nАО &laquo;Региональные электрические сети&raquo;</big></p>\r\n\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n\r\n<table class=\"table table-bordered table-striped\">\r\n	<tbody>\r\n		<tr>\r\n			<td>\r\n			<p style=\"text-align: center;\">№</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Ф.И.О</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Должность в органах управления</p>\r\n\r\n			<p style=\"text-align: center;\">АО &laquo;Региональные электрические сети&raquo;</p>\r\n			</td>\r\n		</tr>\r\n		<tr style=\"height:26.65pt\">\r\n			<td>\r\n			<p style=\"text-align: center;\">1</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Мустафоев Улугбек Мавлонович</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Председатель правления</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p style=\"text-align: center;\">2</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Избосаров Агзам Фахриддинович</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Первый заместитель председателя правления по эксплуатации электрических сетей</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p style=\"text-align: center;\">3</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Гайбуллаев Алвар Келдиёрович</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Первый заместитель председателя правления по вопросам трансформации, инвестиций, инновационного развития, цифровизации и информационных технологий</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p style=\"text-align: center;\">4</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Аскаров Асроржон Акромович</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Заместитель председателя правления по экономике и финансам</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p style=\"text-align: center;\">5</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Носиров Дилшод Баходирович</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Заместитель председателя правления по капитальному строительству</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<p style=\"text-align: center;\">6</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Алимардонов Ойбек Жумакулович</p>\r\n			</td>\r\n			<td>\r\n			<p style=\"text-align: center;\">Заместитель председателя правления по режиму<br />\r\n			и кадрам</p>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n', NULL, NULL, 10798, 1, 3, NULL, 1570104398, 1760968499, ''),
