(165, 88, 'oz', 'MUSTAFOYEV ULUG‘BEK MAVLONOVICH ', '<p><strong>Tug&#39;ilgan yili: </strong>14.08.1968 y.</p>\r\n\r\n<p>1991-yilda Toshkent xalq xo&#39;jaligi institutini tamomlagan.</p>\r\n', '<p><strong>&ldquo;Hududiy elektr tarmoqlari&rdquo; aksiyadorlik jamiyati boshqaruvi raisi</strong></p>\r\n\r\n<p><strong>Telefon</strong>: (78) 150-11-54</p>\r\n\r\n<p><strong>Qabul kunlari:</strong> chorshanba&nbsp;10:00-12:00.</p>\r\n\r\n<p><strong>Elektron&nbsp;pochta:</strong> info@het.uz</p>\r\n', NULL, NULL, 4002, 0, 3, 4, 1570686141, 1734613507, NULL),
(166, 88, 'ru', 'МУСТАФОЕВ УЛУГБЕК МАВЛОНОВИЧ', '<p><strong>Дата рождения</strong>: 14.08.1968 г.</p>\r\n\r\n<p>В 1991 г. окончил Ташкентский институт народного хозяйства.</p>\r\n', '<p><strong>Председатель правления акционерного общества &laquo;Региональные электрические сети&raquo;</strong></p>\r\n\r\n<p><strong>Контактный телефон: </strong>(78) 150-11-54</p>\r\n\r\n<p><strong>Дни приема: </strong>cреда&nbsp;10:00-12:00.</p>\r\n\r\n<p><strong>Электронная почта: </strong>info@het.uz<strong><a href=\"mailto:%20u.mustafoev@het.uz%0d\"> </a></strong></p>\r\n', NULL, NULL, 4226, 0, 3, 4, 1570686154, 1734613577, NULL),
